function parseCSV(text) {
    const lines = text.split(/\r?\n/);
    if (lines.length === 0 || !lines[0]) return [];

    const headers = lines[0].split(',').map(h => h.trim());
    const result = [];

    for (let i = 1; i < lines.length; i++) {
        const line = lines[i].trim();
        if (!line) continue;

        const row = [];
        let inQuotes = false;
        let currentValue = '';

        for (let j = 0; j < line.length; j++) {
            const char = line[j];
            if (char === '"') {
                inQuotes = !inQuotes;
            } else if (char === ',' && !inQuotes) {
                row.push(currentValue.trim());
                currentValue = '';
            } else {
                currentValue += char;
            }
        }
        row.push(currentValue.trim());

        if (row.length >= headers.length) {
            const obj = {};
            headers.forEach((header, index) => {
                let val = row[index];
                if (val && val.startsWith('"') && val.endsWith('"')) {
                    val = val.substring(1, val.length - 1);
                }
                obj[header] = val;
            });
            result.push(obj);
        }
    }
    return result;
}

const webhookInput = $('Webhook').first().json.body || $('Webhook').first().json || {};
const csvText = $('Fetch Inventory CSV').first().json.data || '';

const inventory = parseCSV(csvText).map(row => {
    return {
        id: row.id || '',
        ancho_cm: parseFloat(row.ancho_cm) || 0,
        alto_cm: parseFloat(row.alto_cm) || 0,
        unidades: parseInt(row.unidades, 10) || 0,
        rack: row.rack || '',
        estado: row.estado || ''
    };
});

let itemsToQuote = [];
let totalUnits = 0;

if (webhookInput.origen === 'carrito' && Array.isArray(webhookInput.items)) {
    itemsToQuote = webhookInput.items.map(item => ({
        ancho_cm: parseFloat(item.ancho_cm),
        alto_cm: parseFloat(item.alto_cm),
        qty: parseInt(item.qty, 10) || 1
    }));
} else if (webhookInput.ancho_cm && webhookInput.alto_cm) {
    itemsToQuote = [{
        ancho_cm: parseFloat(webhookInput.ancho_cm),
        alto_cm: parseFloat(webhookInput.alto_cm),
        qty: parseInt(webhookInput.qty, 10) || 1
    }];
} else {
    const msg = webhookInput.message || webhookInput.text || '';
    const match = msg.match(/(\d+(?:\.\d+)?)\s*x\s*(\d+(?:\.\d+)?)/i);
    if (match) {
        const qtyMatch = msg.match(/(?:necesito|quiero|cantidad|unidades|qty)?\s*(\\d+)\s*(?:unidad|unidades|termo|termopanel)/i) || [null, "1"];
        itemsToQuote = [{
            ancho_cm: parseFloat(match[1]),
            alto_cm: parseFloat(match[2]),
            qty: parseInt(qtyMatch[1], 10) || 1
        }];
    }
}

totalUnits = itemsToQuote.reduce((sum, item) => sum + item.qty, 0);

let unitPrice = 25000;
let discountLabel = 'Precio minorista normal';
if (totalUnits >= 40) {
    unitPrice = 15000;
    discountLabel = 'Precio súper mayorista (40+ unidades)';
} else if (totalUnits >= 10) {
    unitPrice = 20000;
    discountLabel = 'Precio mayorista (10-39 unidades)';
}

const itemsSummary = itemsToQuote.map(req => {
    const match = inventory.find(inv => 
        Math.abs(inv.ancho_cm - req.ancho_cm) <= 1.5 && 
        Math.abs(inv.alto_cm - req.alto_cm) <= 1.5 &&
        inv.unidades > 0
    );

    const availableStock = match ? match.unidades : 0;
    const rackLocation = match ? match.rack : 'No especificado';
    const status = availableStock >= req.qty ? 'Disponible' : (availableStock > 0 ? 'Stock Insuficiente' : 'Sin Stock');

    return {
        ancho_cm: req.ancho_cm,
        alto_cm: req.alto_cm,
        solicitado: req.qty,
        stock_disponible: availableStock,
        rack: rackLocation,
        estado: status,
        total_item_precio: req.qty * unitPrice
    };
});

const allAvailable = itemsSummary.length > 0 && itemsSummary.every(item => item.estado === 'Disponible');
const totalCalc = totalUnits * unitPrice;

return {
    origen: webhookInput.origen || 'whatsapp_directo',
    totalUnits,
    unitPrice,
    totalCalc,
    discountLabel,
    itemsSummary,
    allAvailable,
    clientPhone: webhookInput.from || webhookInput.sender || '',
    clientEmail: webhookInput.email || ''
};

const aiOutput = $('Message a model1').first().json;
let text = '';

if (typeof aiOutput === 'string') {
    text = aiOutput;
} else if (aiOutput.content && aiOutput.content.parts && Array.isArray(aiOutput.content.parts)) {
    text = aiOutput.content.parts.map(part => part.text || '').join('');
} else if (aiOutput.message && aiOutput.message.content) {
    text = aiOutput.message.content;
} else if (aiOutput.text) {
    text = aiOutput.text;
} else if (aiOutput.output) {
    text = aiOutput.output;
} else {
    text = JSON.stringify(aiOutput);
}

return [
  {
    json: {
      ok: true,
      encontrado: $('Parse & Calculate Stock/Price').first().json.allAvailable,
      respuesta: text,
      mensaje_sugerido: text,
      clientEmail: $('Parse & Calculate Stock/Price').first().json.clientEmail
    }
  }
];
